<?php
declare(strict_types=1);
require_once __DIR__.'/api-intent-support.php';
function resetNative(EntryEnvironment $x,?callable $guard=null,int $ttl=30):SoSecurity\Password\ResetTokens{return new SoSecurity\Password\ResetTokens($x->store,$ttl,$x->e->clock,$x->boundary,permissionPolicy($x),$x->sessions,$guard??static function():bool{return true;},'managed-test');}
function resetTables():array{return ['account_example'=>['columns'=>['scope'=>'bytes:256','subject'=>'bytes:256','credential_version'=>'bytes:256','address_version'=>'bytes:256','address'=>'bytes:320','password'=>'nullable_bytes:4096','status'=>'bytes:16','verified'=>'int','mfa_required'=>'int','roles'=>'bytes:4096'],'primary'=>['scope','subject']]];}
function resetExpected(EntryEnvironment $x,string $entry,?string $token,string $observed,array $tables=[],int $ttl=30):array
{
    $j=JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE;$state=permissionPolicy($x);$view=$state->resetView('tenant','user',$observed,'address','address_version');$policy=hash('sha256','SoSecurity.Password.Reset.Native.Policy.1.'.json_encode([$state->binding(),$ttl,'managed-test','address','address_version'],$j));$binding=hash('sha256','SoSecurity.Password.Reset.Native.Binding.1.'.json_encode(['managed-test','tenant','user',$view['fingerprint']],$j));$names=array_keys($tables);sort($names);$request=hash('sha256','SoSecurity.Password.Reset.Native.Request.1.'.json_encode(['entry'=>$entry,'subject'=>'user','identity'=>$view['fingerprint'],'binding'=>$binding,'proof'=>$token===null?null:hash('sha256',$token),'tables'=>$names,'observed'=>$observed,'policy'=>$policy],$j));return ['kind'=>'authorized','action'=>'password.reset.'.$entry,'scope'=>hash('sha256',json_encode(['SoSecurity.Account.StateOperation.Scope.1','tenant'],$j)),'actor'=>hash('sha256',json_encode(['SoSecurity.Account.StateOperation.ResetRequest.1','tenant',$request],$j)),'target'=>hash('sha256',json_encode(['SoSecurity.Account.StateOperation.Subject.1','tenant','user'],$j)),'permission'=>$request,'policy'=>$policy,'authorized_at'=>$x->e->clock->time];
}
